SELECT MONTH(order_date) AS order_month, CASE WHEN shipping_fee >= 44 THEN 'high' WHEN shipping_fee >= 17 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND(STDDEV(shipping_fee), 2) AS stddev_shipping_fee, AVG(shipping_fee) AS avg_shipping_fee FROM orders WHERE discount < 0.4 AND channel = 'partner' GROUP BY MONTH(order_date), CASE WHEN shipping_fee >= 44 THEN 'high' WHEN shipping_fee >= 17 THEN 'mid' ELSE 'low' END
